declare(strict_types=1);require __DIR__.'/../../bootstrap.php';require_login();ensure_file_workspace_schema();$title='Trash';require __DIR__.'/../../includes/header.php';$csrf=(string)($_SESSION['_csrf']??'');
?>
<style>.trash-page{max-width:1100px;margin:0 auto}.trash-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;margin-bottom:18px}.trash-head h1{margin:.25rem 0}.trash-list{display:grid;gap:10px}.trash-bulk{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 0 16px}.trash-bulk label{display:flex;align-items:center;gap:8px}.trash-row input{width:18px;height:18px;flex:none;accent-color:#2563eb}.trash-row.selected{border-color:#6d9eff;background:#f4f8ff}.trash-toast{position:fixed;right:16px;bottom:20px;z-index:1000;padding:12px 16px;background:#14243a;color:#fff;border-radius:12px;box-shadow:0 10px 30px #0003}.trash-row{display:flex;align-items:center;gap:14px;padding:14px;border:1px solid var(--border,#e3e8f0);border-radius:13px;background:var(--surface,#fff)}.trash-icon{width:42px;height:42px;border-radius:11px;background:var(--surface-soft,#f2f5fa);display:grid;place-items:center;flex:none}.trash-info{min-width:0;flex:1}.trash-info strong{display:block;overflow-wrap:anywhere}.trash-actions{display:flex;gap:8px;flex-wrap:wrap}.trash-actions button{min-height:38px}.trash-page button:focus-visible{outline:3px solid #7aa7ff;outline-offset:2px}.trash-empty{padding:35px;text-align:center;color:var(--muted,#68758a)}@media(max-width:600px){.trash-row{align-items:flex-start;flex-wrap:wrap}.trash-info{min-width:calc(100% - 60px)}.trash-actions{width:100%;padding-left:56px}.trash-actions button{flex:1}}</style>
<main class="trash-page"><div class="trash-head"><div><span class="eyebrow">FILE STORAGE</span><h1>Trash</h1><p class="muted">Deleted files stay recoverable until the configured retention period expires. Trash continues to count toward your storage quota.</p></div><div class="actions"><a class="btn secondary" href="/files/">Back to files</a><button class="btn secondary" id="refreshTrash" type="button">Refresh</button></div></div><section class="card"><p id="trashStatus" class="muted" role="status" aria-live="polite">Loading Trash…</p><div class="trash-bulk"><label><input type="checkbox" id="selectAllTrash"> Select all</label><span id="trashSelectedCount" class="muted">0 selected</span><button class="btn secondary" id="cancelTrashSelection" type="button">Cancel selection</button><button class="btn" id="bulkRestoreTrash" type="button" disabled>Bulk Restore</button><button class="btn danger" id="bulkDeleteTrash" type="button" disabled>Bulk Delete Permanently</button></div><div id="trashList" class="trash-list"><div class="trash-empty">Loading…</div></div></section></main>
<script>(()=>{'use strict';const csrf=<?=json_encode($csrf)?>,list=document.getElementById('trashList'),status=document.getElementById('trashStatus'),all=document.getElementById('selectAllTrash'),selectedCount=document.getElementById('trashSelectedCount'),restoreAll=document.getElementById('bulkRestoreTrash'),deleteAll=document.getElementById('bulkDeleteTrash');let toastTimer=0;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>{n=Number(n)||0;const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`};function toast(msg){let t=document.getElementById('trashToast');if(!t){t=document.createElement('div');t.id='trashToast';t.className='trash-toast';t.setAttribute('role','status');document.body.appendChild(t)}t.textContent=msg;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),6500)}function confirmDialog(title,message,yes='Continue'){return new Promise(resolve=>{let h=document.getElementById('trashDialog');if(!h){h=document.createElement('div');h.id='trashDialog';h.style.cssText='position:fixed;inset:0;background:#08111dcc;z-index:2000;display:grid;place-items:center;padding:18px';h.innerHTML='<div role="dialog" aria-modal="true" style="background:var(--surface,#fff);color:var(--text,#172033);border-radius:18px;padding:24px;width:min(100%,440px);box-shadow:0 24px 70px #0004"><h2 data-title style="margin-top:0"></h2><p data-message style="white-space:pre-line;overflow-wrap:anywhere"></p><div style="display:flex;justify-content:flex-end;gap:10px"><button type="button" data-no class="btn secondary">Cancel</button><button type="button" data-yes class="btn danger"></button></div></div>';document.body.appendChild(h)}h.querySelector('[data-title]').textContent=title;h.querySelector('[data-message]').textContent=message;h.querySelector('[data-yes]').textContent=yes;h.hidden=false;const finish=v=>{h.hidden=true;h.querySelector('[data-no]').onclick=h.querySelector('[data-yes]').onclick=null;resolve(v)};h.querySelector('[data-no]').onclick=()=>finish(false);h.querySelector('[data-yes]').onclick=()=>finish(true);h.onclick=e=>{if(e.target===h)finish(false)};h.querySelector('[data-yes]').focus()})}async function api(action,body){const opt=body?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({_csrf:csrf,action,...body})}:{};const r=await fetch('/api/files/?action='+encodeURIComponent(action),{credentials:'same-origin',headers:{Accept:'application/json',...(opt.headers||{})},...opt});const j=await r.json().catch(()=>({}));if(!r.ok||j.error)throw Error(j.error||'Request failed');return j}function chosen(){return [...list.querySelectorAll('.trash-select:checked')].map(x=>Number(x.value))}function sync(){const ids=chosen(),checks=[...list.querySelectorAll('.trash-select')];selectedCount.textContent=ids.length+' selected';restoreAll.disabled=deleteAll.disabled=!ids.length;all.checked=checks.length>0&&checks.every(x=>x.checked);all.indeterminate=checks.some(x=>x.checked)&&!all.checked;list.querySelectorAll('.trash-row').forEach(r=>r.classList.toggle('selected',!!r.querySelector('.trash-select')?.checked))}async function load(){status.textContent='Loading Trash…';try{const j=await api('trash_list');const items=j.items||[];status.textContent=`${j.total||items.length} file(s) in Trash. Items are not publicly accessible while trashed.`;if(!items.length){list.innerHTML='<div class="trash-empty"><strong>Trash is empty</strong><p>Files you delete will appear here and can be restored.</p></div>';sync();return}list.innerHTML=items.map(x=>`<article class="trash-row" data-id="${Number(x.id)}"><input class="trash-select" type="checkbox" value="${Number(x.id)}" aria-label="Select ${esc(x.original_name)}"><div class="trash-icon" aria-hidden="true">▤</div><div class="trash-info"><strong>${esc(x.original_name)}</strong><span class="muted">${esc(x.relative_path||'')} · ${fmt(x.size_bytes)} · Trashed ${esc(x.trashed_at||'')}</span></div><div class="trash-actions"><button class="btn secondary" data-action="restore" data-id="${Number(x.id)}">Restore</button><button class="btn danger" data-action="delete" data-id="${Number(x.id)}">Delete permanently</button></div></article>`).join('');sync()}catch(e){list.innerHTML='<div class="trash-empty">Could not load Trash.</div>';status.textContent=e.message}}list.addEventListener('change',e=>{if(e.target.matches('.trash-select'))sync()});all.addEventListener('change',()=>{list.querySelectorAll('.trash-select').forEach(x=>x.checked=all.checked);sync()});document.getElementById('cancelTrashSelection').onclick=()=>{list.querySelectorAll('.trash-select').forEach(x=>x.checked=false);sync()};async function bulk(kind){const ids=chosen();if(!ids.length)return;if(kind==='delete'&&!await confirmDialog('Delete permanently?',`Permanently delete ${ids.length} item(s)? This cannot be undone.`,'Delete permanently'))return;let ok=0,failed=[];for(const id of ids){try{await api(kind==='restore'?'restore':'permanent_delete',{id});ok++}catch(e){failed.push('#'+id+': '+e.message)}}toast(kind==='restore'?'♻️ '+ok+' item(s) restored':'🗑️ '+ok+' item(s) permanently deleted');if(failed.length)status.textContent=failed.join(' · ');await load()}restoreAll.onclick=()=>bulk('restore');deleteAll.onclick=()=>bulk('delete');list.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b)return;const id=Number(b.dataset.id);try{if(b.dataset.action==='delete'&&!await confirmDialog('Delete permanently?','This item will be permanently deleted and cannot be restored.','Delete permanently'))return;if(b.dataset.action==='restore'){await api('restore',{id});toast('♻️ File restored')}else{await api('permanent_delete',{id});toast('🗑️ File permanently deleted')}await load()}catch(err){status.textContent=err.message||'Operation failed.'}});document.getElementById('refreshTrash').addEventListener('click',load);load()})();</script>
